const slackAPI = require('slack-api-wrapper'); // Assuming you've installed a Slack API library like this one

/**
 * Posts a message to a specified Slack channel using the Slack API.
 *
 * @param {string} text - The content of the message to post.
 * @param {string} channelId - The ID of the Slack channel to send the message to.
 * @param {object} [slackToken] -  An object with a 'accessToken' property containing your verified Slack bot's access token ( **required for API interaction**).
 * @returns {Promise<object>} Resolves with the Slack API's response object on success, otherwise rejects with an error.
 */
async function postToSlack(text, channelId, slackToken) {
  if (!slackToken || !slackToken.accessToken) {
    return Promise.reject(new Error("Missing required 'slackToken.accessToken' for API call."));
  }

  const slack = new slackAPI({ token: slackToken.accessToken }); // Initialize Slack API client

  try {
    const response = await slack.chat.postMessage({
      channel: channelId,
      text: text,
      // Add optional parameters like thread_ts, attachments, etc. for richer messages here
    });
    return response; 
  } catch (error) {
    console.error("Slack API Error:", error);
    return Promise.reject(error); 
  }
}

// Example Usage:
const mySlackToken = { accessToken: 'YOUR_BOT_ACCESS_TOKEN' }; // Replace with your actual token
postToSlack("Hello from my JavaScript function!", 'C123ABC456DEF', mySlackToken)
  .then(result => console.log('Message posted successfully:', result))
  .catch(err => console.error('Posting failed:', err));
